const icon = (name) => `<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name] || icons.info}</svg>`;
const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
const esc = (value) => String(value ?? '').replace(/[&<>"']/g, (char) => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const attr = esc;
const known = (value, fallback = 'Unknown') => value == null || value === '' ? fallback : esc(Array.isArray(value) ? value.join(', ') : value);
const human = (value) => String(value || '').replaceAll('_', ' ').replace(/\b\w/g, x => x.toUpperCase());
const num = (value, fallback = 0) => Number.isFinite(Number(value)) ? Number(value) : fallback;
const fmt = (value) => Number.isFinite(Number(value)) ? Number(value).toLocaleString(undefined, {maximumFractionDigits:2}) : '—';
const date = (value, includeTime = false) => { if (!value) return 'Not yet'; const d = new Date(value); return Number.isNaN(d.getTime()) ? esc(value) : d.toLocaleDateString(undefined, {month:'short',day:'numeric',year:'numeric', ...(includeTime ? {hour:'numeric',minute:'2-digit'} : {})}); };
const safeUrl = (value) => { if (!value) return ''; try { const u = new URL(value, location.origin); return ['http:','https:'].includes(u.protocol) ? u.href : ''; } catch { return ''; } };
const list = (data) => Array.isArray(data) ? data : data?.items || [];
const isSimulation = (bridge) => ['simulation','simulate','dry_run'].includes(bridge?.mode);
const state = {route:'overview',beans:[],recipes:[],cards:[],jobs:[],status:{},settings:{},session:{},query:'',filter:'all',importProfile:null,refreshing:false,modalContext:null};
const navigation = [{id:'overview',label:'Overview',icon:'overview'},{id:'beans',label:'Bean library',icon:'bean'},{id:'recipes',label:'Recipes',icon:'recipe'},{id:'cards',label:'NFC cards',icon:'card'},{id:'settings',label:'Settings',icon:'settings'}];
const modal = $('#modal');
let modalReturnFocus = null;
let submitting = false;

function hydrateIcons(root = document) { $$('[data-icon]', root).forEach(el => { el.innerHTML = icon(el.dataset.icon); }); }
function toast(message, error = false) {
  const el = document.createElement('div'); el.className = `toast${error ? ' error' : ''}`; el.setAttribute('role', error ? 'alert' : 'status');
  el.innerHTML = `${icon(error ? 'warning' : 'check')}<span>${esc(message)}</span><button class="icon-button" aria-label="Dismiss notification">${icon('close')}</button>`;
  $('button', el).addEventListener('click', () => el.remove()); $('#toasts').append(el); setTimeout(() => el.remove(), error ? 10000 : 5500);
}
function detailMessage(detail) {
  if (typeof detail === 'string') return detail;
  if (Array.isArray(detail)) return detail.map(x => `${(x.loc || []).filter(x => x !== 'body').join(' › ')}: ${x.msg || JSON.stringify(x)}`).join('; ');
  return detail?.message || JSON.stringify(detail || 'The request could not be completed.');
}
async function api(path, options = {}) {
  const headers = {...(options.headers || {})};
  if (options.body && !(options.body instanceof FormData)) {headers['Content-Type']='application/json';options.body=JSON.stringify(options.body);}
  let response;
  try { response = await fetch(path, {credentials:'same-origin',cache:'no-store',...options,headers}); }
  catch { throw new Error('The local server could not be reached. Check that it is running and try again.'); }
  const data = response.status === 204 ? {} : await response.json().catch(() => ({}));
  if (!response.ok) { const error=new Error(detailMessage(data.detail || data.error || `Request failed (${response.status})`)); error.status=response.status; throw error; }
  return data;
}
async function withForm(form, fn) {
  if (submitting) return;
  submitting=true;const buttons=$$('button[type=submit]',form);buttons.forEach(b=>b.disabled=true);const error=$('.form-error',form);if(error)error.textContent='';
  try { await fn(); } catch(e) { if(error)error.textContent=e.message;else toast(e.message,true); }
  finally { submitting=false;buttons.forEach(b=>b.disabled=false); }
}
function openModal(title, subtitle, body, {wide=false,narrow=false,prefix=''}={}) {
  modalReturnFocus=document.activeElement;modal.className=`modal${wide?' wide':''}${narrow?' narrow':''}`;
  $('#modal-content').innerHTML=`<div class="modal-header"><div>${prefix?`<div class="modal-title-prefix">${esc(prefix)}</div>`:''}<h2 id="modal-title">${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div><button class="icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button></div><div class="modal-body">${body}</div>`;
  modal.setAttribute('aria-labelledby','modal-title');if(!modal.open)modal.showModal();modal.scrollTop=0;
}
function closeModal() {modal.close();state.modalContext=null;$('#modal-content').innerHTML='';document.body.classList.remove('login-only');modalReturnFocus?.focus?.();}
function showModalLoading(title) {openModal(title,'Loading the latest details…','<div class="loading-state"><span class="spinner"></span></div>');}
function field(name,label,value='',type='text',extra='',help='') {return `<div class="field"><label for="f-${attr(name)}">${esc(label)}</label><input id="f-${attr(name)}" name="${attr(name)}" type="${attr(type)}" value="${attr(value ?? '')}" ${extra}>${help?`<small>${esc(help)}</small>`:''}</div>`;}
function textarea(name,label,value='',extra='',help=''){return `<div class="field"><label for="f-${attr(name)}">${esc(label)}</label><textarea id="f-${attr(name)}" name="${attr(name)}" ${extra}>${esc(value ?? '')}</textarea>${help?`<small>${esc(help)}</small>`:''}</div>`;}
function selectField(name,label,value,options,extra=''){return `<div class="field"><label for="f-${attr(name)}">${esc(label)}</label><select id="f-${attr(name)}" name="${attr(name)}" ${extra}>${options.map(o=>{const [val,text]=Array.isArray(o)?o:[o,human(o)];return `<option value="${attr(val)}" ${String(val)===String(value)?'selected':''}>${esc(text)}</option>`;}).join('')}</select></div>`;}
function callout(text,type='info',title=''){return `<div class="callout ${attr(type)}">${icon(type==='warning'||type==='danger'?'warning':'info')}<p>${title?`<strong>${esc(title)}</strong> `:''}${text}</p></div>`;}
function emptyState(title,description,action='',label='',symbol='bean',compact=false){return `<div class="empty-state${compact?' compact':''}"><span class="empty-icon">${icon(symbol)}</span><h3>${esc(title)}</h3><p>${esc(description)}</p>${action?`<button class="button ${compact?'button-small button-outline':'button-primary'}" data-action="${attr(action)}">${icon('plus')}${esc(label)}</button>`:''}</div>`;}
function heading(title,description,actions='',eyebrow='YOUR COFFEE WORKSPACE'){return `<div class="page-heading"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p>${esc(description)}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`;}
function button(action,label,symbol='plus',style='primary',data=''){return `<button class="button button-${attr(style)}" data-action="${attr(action)}" ${data}>${icon(symbol)}${esc(label)}</button>`;}
function beanName(id){return state.beans.find(b=>String(b.id)===String(id))?.name || 'Unassigned coffee';}
function cardLabel(id){return state.cards.find(c=>String(c.id)===String(id))?.label || 'Card';}
function cardBackupState(card){
  if(card.needs_fresh_read)return {label:'Fresh read required',tone:'red'};
  if(card.verified_at)return {label:'Read-back verified',tone:''};
  if(num(card.hardware_backup_count)>0)return {label:'Hardware backup saved',tone:''};
  if(num(card.simulation_backup_count)>0)return {label:num(card.imported_backup_count)>0?'Reference + simulation':'Simulation only',tone:'orange'};
  if(num(card.imported_backup_count)>0)return {label:'Reference imported',tone:'gray'};
  return {label:num(card.backup_count)>0?'Backup records available':'Needs first backup',tone:'gray'};
}
function cardBackupPill(card){const status=cardBackupState(card);return `<span class="pill ${status.tone}">${status.label}</span>`;}
function recipeName(id){return state.recipes.find(r=>String(r.id)===String(id))?.name || 'No recipe assigned';}
function statusPill(status){const s=String(status||'unknown');const type=['verified','completed','succeeded','success','online'].includes(s)?'':['failed','error','unverified'].includes(s)?'red':['pending','queued','awaiting_confirmation','dry_run','simulated','simulation'].includes(s)?'orange':'gray';return `<span class="pill ${type}">${esc(human(s))}</span>`;}
function renderNavigation(){
  $('#navigation').innerHTML=navigation.map((n,i)=>`${i===4?'<div class="nav-divider"></div>':''}<a href="#${n.id}" class="nav-link${state.route===n.id?' active':''}" ${state.route===n.id?'aria-current="page"':''}>${icon(n.icon)}<span>${n.label}</span></a>`).join('');
  $('#breadcrumb').textContent=navigation.find(n=>n.id===state.route)?.label || 'Overview';
  $('#session-button').textContent=(state.session.username || 'B').charAt(0).toUpperCase();
}
function coffeeArt(){return `<div class="hero-orbit"></div><div class="hero-art" aria-hidden="true"><svg viewBox="0 0 240 240"><path d="M44 205h168" stroke="#a8b799"/><ellipse cx="134" cy="205" rx="58" ry="8" fill="#c7d2b6" stroke="none"/><path d="M106 33h66l-7 10h-53Z" fill="#e9eddc" stroke="#7b9071"/><path d="M112 43h53l-8 91h-37Z" fill="#e1e8d2" stroke="#7b9071"/><path d="M118 49h41l-7 64h-28Z" fill="#ccdabd" stroke="#8c9f7d"/><path d="M120 134h38v9h-38Z" fill="#829779" stroke="#7b9071"/><path d="M126 143v12m26-12v12"/><path d="M134 151v9m9-9v10" stroke-dasharray="2 3"/><path d="M101 166h74l-8 36h-58Z" fill="#f9f8e8" stroke="#7b9071"/><path d="M175 171h7c15 0 15 21-12 21" stroke="#7b9071" stroke-width="3"/><ellipse cx="138" cy="166" rx="37" ry="6" fill="#e2e8d5" stroke="#7b9071"/><ellipse cx="138" cy="167" rx="25" ry="3" fill="#9eaa86" stroke="none"/><path d="M103 145H83V62h22M170 62h13v97" stroke="#829479" stroke-width="4"/><path d="M81 202V63a7 7 0 0 1 7-7h17m64 0h11a7 7 0 0 1 7 7v139" stroke="#91a17f" stroke-width="3"/><path d="M71 204h127" stroke="#859875" stroke-width="4"/><path d="M55 145c9-7 15 3 6 11s-15 0-6-11Zm-3 10 12-10M198 112c9-7 15 3 6 11s-15 0-6-11Zm-3 10 12-10" stroke="#b1bb9d"/><path d="M51 74c-2-7 5-10 4-16m147 115c-2-7 5-10 4-16" stroke="#b1bb9d"/></svg></div>`;}
function overview(){
  const b=state.status.bridge||{};const hasRecipes=state.recipes.length>0;
  return `${heading('A little ritual. A better cup.','Your coffees, recipes, and cards. All in one familiar place.',`<div class="date-chip">${icon('calendar')}${new Date().toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'})}</div>`)}
  <div class="stats-grid">${[['bean',state.beans.length,'Coffees in your library','beans'],['recipe',state.recipes.length,'Saved brew recipes','recipes'],['card',state.cards.length,'Cards in your collection','cards']].map(([i,v,l,r])=>`<a class="stat-card" href="#${r}"><div class="stat-icon">${icon(i)}</div><div><div class="stat-value">${v.toString().padStart(2,'0')}</div><div class="stat-label">${l}</div></div><span class="stat-arrow">${icon('arrow')}</span></a>`).join('')}</div>
  <div class="overview-grid"><div><section class="hero-card"><div class="hero-copy"><div class="eyebrow">FROM COFFEE BAG TO FIRST SIP</div><h2>${hasRecipes?'Your next good cup<br>is already taking shape.':'Make room for your<br>next favorite coffee.'}</h2><p>${hasRecipes?'Fine-tune a recipe, save it to a card, and enjoy your coffee just the way you like it.':'Bring in a coffee profile, shape your 18 g recipe, and make it part of your morning ritual.'}</p>${button(hasRecipes?'new-recipe':'import',hasRecipes?'Create a recipe':'Import a coffee profile',hasRecipes?'plus':'upload')}</div>${coffeeArt()}</section>
    <section><div class="section-heading"><div><h2>Your brew recipes</h2><p>Made by you. Refined with every cup.</p></div><a class="text-link" href="#recipes">View all ${icon('arrow')}</a></div>${hasRecipes?`<div class="recipe-list">${state.recipes.slice(0,3).map(recipeCard).join('')}</div>`:`<div class="panel">${emptyState('Your first recipe belongs here','Import an approved coffee profile or build a recipe from scratch. Every new version stays in your library.','new-recipe','Create a recipe','recipe')}</div>`}</section>
    ${state.jobs.length?`<section class="mt-16"><div class="section-heading"><h2>Recent card activity</h2><a class="text-link" href="#cards">View cards ${icon('arrow')}</a></div><div class="panel">${state.jobs.slice(0,4).map(jobItem).join('')}</div></section>`:''}
  </div><aside class="overview-aside"><section class="panel workflow-panel"><div class="panel-header"><div><h2>A simple brewing flow</h2><p>Three steps to your next cup.</p></div>${icon('coffee')}</div><div class="workflow">${[['1','Save your coffee','Add its origin, tasting notes, and a recipe you’ve reviewed.'],['2','Prepare your card','Back up, review, and approve a write from your Windows PC.'],['3','Tap. Brew. Enjoy.','Tap the card on your offline xBloom and make it your own.']].map(([n,t,d])=>`<div class="workflow-step"><span class="step-number">${n}</span><div><h3>${t}</h3><p>${d}</p></div></div>`).join('')}</div></section>
  <section class="panel bridge-panel"><div class="bridge-top"><span class="device-icon">${icon('device')}</span><div><h3>Windows card bridge</h3><p>Your connection to Proxmark</p></div></div>${statusPill(b.online?(isSimulation(b)?'simulation':'online'):'offline')}<p class="bridge-note">${b.online?`Connected${b.name?` as ${esc(b.name)}`:''}. ${isSimulation(b)?'Simulation is enabled. Physical cards will not be changed.':'Card writes wait for your confirmation.'}`:'Start the bridge on your Windows PC when you’re ready to read or write a card.'}</p><div class="mini-divider"></div><a class="text-link" href="#settings">Connection & settings ${icon('arrow')}</a></section></aside></div>`;
}
function beanCard(bean,index){
  const flavors=Array.isArray(bean.flavor_notes)?bean.flavor_notes:[];const photo=safeUrl(bean.photo_url);const colors=['#e9eadb','#e7e7d8','#eee5d9','#e2e9df'];
  return `<article class="bean-card"><div class="bean-art" style="background:${colors[index%colors.length]}">${photo?`<img src="${attr(photo)}" alt="${attr(bean.name)} coffee bag" loading="lazy">`:`<div class="bean-bag"><div class="bag-label">${icon('bean')}<span>${esc(bean.roaster||'Your coffee')}</span></div></div>`}<span class="origin-label">${known(bean.country,'Origin unknown')}</span></div><div class="bean-content"><div class="bean-roaster">${known(bean.roaster,'Roaster unknown')}</div><h2 class="bean-name">${esc(bean.name)}</h2><p class="bean-meta">${[bean.process,bean.roast_level].filter(Boolean).map(esc).join(' · ') || 'Add processing and roast details'}</p><div class="chips">${flavors.length?flavors.slice(0,4).map(f=>`<span class="chip">${esc(f)}</span>`).join(''):'<span class="chip">Tasting notes to discover</span>'}</div><div class="bean-footer"><span class="muted" style="font-size:10px">${bean.rating?`<span class="rating-stars" aria-label="${attr(bean.rating)} out of 5 stars">${'★'.repeat(Math.round(bean.rating))}${'☆'.repeat(5-Math.round(bean.rating))}</span>`:`${state.recipes.filter(r=>String(r.bean_id)===String(bean.id)).length} recipes`}</span><button class="button button-small button-outline" data-action="view-bean" data-id="${attr(bean.id)}">View coffee ${icon('arrow')}</button></div></div></article>`;
}
function beansPage(){const q=state.query.toLowerCase();const beans=state.beans.filter(b=>[b.name,b.roaster,b.country,b.process,...(b.flavor_notes||[])].some(v=>String(v||'').toLowerCase().includes(q)));return `${heading('Your bean library','A home for the coffees you love, and the ones you’re yet to discover.',button('new-bean','Add coffee'),'KNOW YOUR COFFEE')}<div class="toolbar"><div class="search-box">${icon('search')}<input id="page-search" type="search" placeholder="Search coffee, roaster, origin…" value="${attr(state.query)}" aria-label="Search coffees"></div><span class="record-count">${beans.length} ${beans.length===1?'coffee':'coffees'}</span></div><div id="results">${beans.length?`<div class="card-grid">${beans.map(beanCard).join('')}</div>`:`<div class="panel">${emptyState(q?'No coffees match your search':'Start with a coffee you love',q?'Try a different coffee name, roaster, or origin.':'Add the details from your bag, or import a profile you’ve reviewed in Codex.',q?'':'new-bean','Add your first coffee','bean')}</div>`}</div>`;}
function recipeCard(recipe){return `<article class="recipe-card"><div class="recipe-card-icon">${icon('recipe')}</div><div class="recipe-card-copy"><h3>${esc(recipe.name)}</h3><p class="recipe-card-subtitle">${esc(beanName(recipe.bean_id))} <span aria-hidden="true">·</span> Version ${num(recipe.version,1)}</p><div class="recipe-metrics"><div class="recipe-metric">${fmt(recipe.dose_g)} g<small>COFFEE</small></div><div class="recipe-metric">1:${fmt(recipe.ratio)}<small>RATIO</small></div><div class="recipe-metric">${fmt(recipe.total_water_ml)} ml<small>WATER</small></div><div class="recipe-metric">${recipe.pours?.length||0} pours<small>BREW STEPS</small></div></div></div><div class="recipe-card-actions"><span class="pill">${recipe.cup_type==='xpod'?'xPod':recipe.cup_type==='other'?'Other dripper':'Omni dripper'}</span><button class="button button-small button-outline" data-action="view-recipe" data-id="${attr(recipe.id)}">View recipe ${icon('arrow')}</button></div></article>`;}
function recipesPage(){const q=state.query.toLowerCase();const recipes=state.recipes.filter(r=>[r.name,beanName(r.bean_id)].some(v=>v.toLowerCase().includes(q)));return `${heading('Recipes worth repeating','Build your brew, keep every version, and find your sweet spot.',button('new-recipe','Create recipe'),'YOUR BREW NOTEBOOK')}<div class="toolbar"><div class="search-box">${icon('search')}<input id="page-search" type="search" placeholder="Search recipes or coffees…" value="${attr(state.query)}" aria-label="Search recipes"></div><span class="record-count">${recipes.length} ${recipes.length===1?'recipe':'recipes'}</span></div>${recipes.length?`<div class="recipe-list">${recipes.map(recipeCard).join('')}</div>`:`<div class="panel">${emptyState(q?'No recipes found':'Every good cup starts with a recipe',q?'Try a different recipe or coffee name.':'Begin with an 18 g recipe and adjust the pours, temperature, and grind to suit your coffee.',q?'':'new-recipe','Create your first recipe','recipe')}</div>`}`;}
function cardsPage(){return `${heading('Your card collection','Prepare a recipe, confirm your card, and keep a verified backup.',button('new-card','Register card'),'READY FOR YOUR NEXT BREW')}${callout('Each physical card gets its own label. Custom cards can share the same UID, so always match the label to the card on your reader.','info')}${state.cards.length?`<div class="card-inventory">${state.cards.map(c=>`<article class="nfc-card"><div class="nfc-card-heading"><span class="nfc-card-icon">${icon('card')}</span>${cardBackupPill(c)}</div><h3>${esc(c.label)}</h3><div class="nfc-uid mono">${c.uid?esc(c.uid):'UID recorded after first read'}</div><div class="status-row"><span>Saved recipe</span><strong>${c.recipe_id?esc(recipeName(c.recipe_id)):'Not assigned'}</strong></div><div class="status-row"><span>Saved backup records</span><strong>${num(c.backup_count)}</strong></div><div class="nfc-card-footer"><span class="muted" style="font-size:10px">Custom NFC card</span><button class="button button-small button-outline" data-action="view-card" data-id="${attr(c.id)}">Manage card ${icon('arrow')}</button></div></article>`).join('')}</div>`:`<div class="panel">${emptyState('A place for every coffee card','Give your custom card a physical label, then save a backup before preparing its first recipe.','new-card','Register your first card','card')}</div>`}${state.jobs.length?`<section class="mt-16"><div class="section-heading"><h2>Card activity</h2><button class="text-link" data-action="refresh">${icon('refresh')}Refresh</button></div><div class="panel">${state.jobs.slice(0,12).map(jobItem).join('')}</div></section>`:''}`;}
function jobItem(job){
  const detail=job.error||job.message||job.result?.message||'';
  const recovery=job.status==='running'&&!state.status.bridge?.online;
  return `<div class="job-item"><span class="job-icon">${icon(job.kind==='read'?'download':job.kind==='restore'?'refresh':'card')}</span><div class="job-copy"><strong>${esc(human(job.kind||'Card job'))} · ${esc(cardLabel(job.card_id))}</strong><small>${date(job.created_at,true)}${job.mode==='simulation'?' · Simulation only':''}${detail?` · ${esc(detail)}`:''}</small></div><div class="job-actions">${statusPill(job.status)}${job.status==='queued'?`<button class="text-link" data-action="cancel-job" data-id="${attr(job.id)}">Cancel</button>`:''}${recovery?`<button class="text-link danger-text" data-action="resolve-job" data-id="${attr(job.id)}">Resolve interruption</button>`:''}</div></div>`;
}
function settingsPage(){const b=state.status.bridge||{};return `${heading('A workspace that stays yours','Manage local access, the Windows bridge, and your library backups.','','WORKSPACE SETTINGS')}<div class="settings-grid"><section class="panel settings-section"><h2>Workspace & access</h2><p>Your recipe manager runs on your own server. Keep access within your local network.</p><div class="status-row"><span>Signed in as</span><strong>${esc(state.session.username||'Local account')}</strong></div><div class="status-row"><span>Application version</span><strong>${esc(state.settings.version||'1.0')}</strong></div><div class="status-row"><span>xBloom connection</span><strong>Offline · NFC only</strong></div><div class="status-row"><span>Default coffee dose</span><strong>18 g</strong></div><div class="inline-actions">${button('create-api-token','Create import token','lock','outline')}${button('logout','Sign out','logout','quiet')}</div><p class="privacy-caption">${icon('shield')}Tokens are shown once. Keep them in your local credentials.</p></section><section class="panel settings-section"><h2>Windows Proxmark bridge</h2><p>Keep your Windows PC and USB Proxmark connected when working with cards.</p><div class="status-row"><span>Connection</span>${statusPill(b.online?'online':'offline')}</div><div class="status-row"><span>Bridge mode</span><strong>${b.mode?esc(human(b.mode)):'Not connected'}</strong></div><div class="status-row"><span>Last seen</span><strong>${b.last_seen?date(b.last_seen,true):'Not yet'}</strong></div><div class="inline-actions">${button('bridge-help','Setup instructions','device','outline')}${button('create-bridge-token','Create bridge token','lock','quiet')}</div></section><section class="panel settings-section"><h2>Back up your coffee library</h2><p>Download an archive of your database, bag photos, and stored card backups. Keep a copy somewhere separate from the server.</p><ul class="settings-checklist"><li>${icon('check')}Bean profiles, ratings, and tasting notes</li><li>${icon('check')}Recipes and their complete version history</li><li>${icon('check')}Card records and saved dump files</li></ul><a class="button button-outline" href="/api/backup" download>${icon('download')}Download workspace backup</a></section><section class="panel settings-section"><h2>Bring a profile in from Codex</h2><p>Ask Codex for a structured coffee profile and an 18 g recipe. Review the source facts and brewing recommendations before importing.</p>${button('import','Review & import a profile','upload','outline')}<div class="settings-links"><button class="text-link" data-action="import-format">View the import format ${icon('arrow')}</button><p>Missing coffee details stay unknown. Recipe suggestions are recommendations, and NFC compatibility is checked separately.</p></div></section></div>`;}
function render(){renderNavigation();const pages={overview,beans:beansPage,recipes:recipesPage,cards:cardsPage,settings:settingsPage};$('#main').innerHTML=(pages[state.route]||overview)();hydrateIcons();}
async function refresh({renderPage=true,quiet=false}={}){
  if(state.refreshing)return;state.refreshing=true;
  try {const [status,beans,recipes,cards,jobs,settings]=await Promise.all([api('/api/status'),api('/api/beans'),api('/api/recipes'),api('/api/cards'),api('/api/jobs'),api('/api/settings')]);Object.assign(state,{status,beans:list(beans),recipes:list(recipes),cards:list(cards),jobs:list(jobs),settings});$('#connection-banner').hidden=true;if(renderPage)render();}
  catch(e){if(e.status===401){state.session.authenticated=false;showAuth();}else if(quiet){$('#connection-banner').textContent=e.message;$('#connection-banner').hidden=false;}else throw e;}
  finally{state.refreshing=false;}
}
function changeRoute(){const route=location.hash.slice(1).split('?')[0]||'overview';state.route=navigation.some(n=>n.id===route)?route:'overview';state.query='';$('#sidebar').classList.remove('open');$('#nav-backdrop').hidden=true;$('#menu-toggle').setAttribute('aria-expanded','false');if(state.session.authenticated){render();window.scrollTo(0,0);}}
function showAuth(){
  const setup=!state.session.configured;document.body.classList.add('login-only');modal.className='modal narrow';modalReturnFocus=null;
  $('#modal-content').innerHTML=`<div class="auth-header"><div class="auth-mark" aria-hidden="true">✳</div><h2 id="modal-title">${setup?'Welcome to your coffee space.':'Welcome back.'}</h2><p>${setup?'Create your local account to start building your coffee library.':'Sign in to your local recipe workspace.'}</p></div><div class="auth-body"><form id="auth-form">${field('username','Username',state.session.username||'', 'text','required autocomplete="username" minlength="2" maxlength="64"')}${`<div class="mt-16">${field('password','Password','','password',`required autocomplete="${setup?'new-password':'current-password'}" ${setup?'minlength="12"':''}`,setup?'Choose a password with at least 12 characters.':'')}</div>`}${setup?`<div class="mt-16">${field('confirm_password','Confirm password','','password','required autocomplete="new-password" minlength="12"')}</div>`:''}<div class="form-error" role="alert"></div><button class="button button-primary" type="submit">${icon('lock')}${setup?'Create my workspace':'Sign in'}</button></form><p class="auth-footer">Your library stays on your own server.</p></div>`;
  modal.setAttribute('aria-labelledby','modal-title');if(!modal.open)modal.showModal();
  $('#auth-form').addEventListener('submit',e=>{e.preventDefault();withForm(e.target,async()=>{const fd=new FormData(e.target);if(setup&&fd.get('password')!==fd.get('confirm_password'))throw new Error('The passwords do not match.');await api(setup?'/api/setup':'/api/session',{method:'POST',body:{username:fd.get('username'),password:fd.get('password')}});state.session=await api('/api/session');closeModal();await refresh();});});
}

// Coffee library
function editBean(id){const bean=state.beans.find(b=>String(b.id)===String(id))||{};state.modalContext={type:'bean',id};
  openModal(id?'Edit your coffee':'Add a coffee','Start with what you know. Leave unavailable details blank.',`<form id="bean-form"><section class="form-section"><h3>The essentials</h3><p>Information from the bag or roaster’s product page.</p><div class="field-grid">${field('name','Coffee name',bean.name,'text','required maxlength="160" placeholder="e.g. La Esperanza"')}${field('roaster','Roaster',bean.roaster,'text','maxlength="160" placeholder="Who roasted it?"')}<div class="span-full">${field('product_url','Original product URL',bean.product_url,'url','placeholder="https://roaster.com/coffee/…"')}</div>${field('roast_date','Roast date',bean.roast_date,'date')}${field('roast_level','Roast level',bean.roast_level,'text','placeholder="e.g. Light or medium"')}</div></section><section class="form-section"><h3>Where it comes from</h3><p>Unknown details will stay unknown.</p><div class="field-grid three">${field('country','Country',bean.country)}${field('region','Region',bean.region)}${field('farm','Farm / producer',bean.farm)}${field('elevation','Elevation',bean.elevation,'text','placeholder="e.g. 1,800–2,000 masl"')}${field('process','Process',bean.process,'text','placeholder="e.g. Washed"')}${field('variety','Variety',bean.variety,'text','placeholder="e.g. Bourbon"')}</div></section><section class="form-section"><h3>In the cup</h3><div class="field-grid"><div class="span-full">${field('flavor_notes','Roaster tasting notes',(bean.flavor_notes||[]).join(', '),'text','placeholder="Peach, honey, black tea"','Separate tasting notes with commas.')}</div><div class="span-full">${textarea('notes','Your tasting notes',bean.notes,'placeholder="What did you enjoy? What would you change next time?"')}</div>${selectField('rating','Your rating',bean.rating||'',[['','Not rated'],[1,'1 · Not for me'],[2,'2 · Okay'],[3,'3 · Good'],[4,'4 · Really good'],[5,'5 · A favorite']])}${field('photo','Coffee bag photo','','file','accept="image/jpeg,image/png,image/webp"','Optional. JPEG, PNG, or WebP.')}</div></section><div class="form-error" role="alert"></div><div class="form-actions">${id?`<button type="button" class="button button-danger left" data-action="delete-bean" data-id="${attr(id)}">${icon('trash')}Delete</button>`:''}<button type="button" class="button button-outline" data-action="close-modal">Cancel</button><button class="button button-primary" type="submit">${icon('check')}${id?'Save coffee':'Add to library'}</button></div></form>`,{wide:true});
  $('#bean-form').addEventListener('submit',e=>{e.preventDefault();withForm(e.target,async()=>{const fd=new FormData(e.target);const data={};for(const k of ['name','roaster','product_url','country','region','farm','elevation','process','variety','roast_level','roast_date','notes'])data[k]=String(fd.get(k)||'').trim()||null;data.flavor_notes=String(fd.get('flavor_notes')||'').split(',').map(x=>x.trim()).filter(Boolean);data.rating=fd.get('rating')?Number(fd.get('rating')):null;data.notes=String(fd.get('notes')||'').trim();data.provenance=bean.provenance||{source:'manual',reviewed:'true'};const saved=await api(id?`/api/beans/${encodeURIComponent(id)}`:'/api/beans',{method:id?'PATCH':'POST',body:data});const photo=fd.get('photo');if(photo instanceof File&&photo.size){const upload=new FormData();upload.append('file',photo);try{await api(`/api/beans/${encodeURIComponent(saved.id)}/photo`,{method:'POST',body:upload});}catch(err){toast(`Coffee saved. Photo upload failed: ${err.message}`,true);}}closeModal();await refresh();toast(id?'Coffee updated.':'Coffee added to your library.');});});
}
function viewBean(id){const bean=state.beans.find(b=>String(b.id)===String(id));if(!bean)return;const recipes=state.recipes.filter(r=>String(r.bean_id)===String(id));const photo=safeUrl(bean.photo_url);const source=safeUrl(bean.product_url);openModal(bean.name,bean.roaster||'Roaster unknown',`${photo?`<div class="detail-photo"><img src="${attr(photo)}" alt="${attr(bean.name)} coffee bag"></div>`:''}<div class="badge-row">${bean.rating?`<span class="rating-stars" aria-label="${bean.rating} out of 5 stars">${'★'.repeat(Math.round(bean.rating))}${'☆'.repeat(5-Math.round(bean.rating))}</span>`:'<span class="pill gray">Not rated yet</span>'}<span class="pill gray">Source details</span></div><dl class="info-grid">${[['Country',bean.country],['Region',bean.region],['Farm / producer',bean.farm],['Elevation',bean.elevation],['Process',bean.process],['Variety',bean.variety],['Roast level',bean.roast_level],['Roast date',bean.roast_date?date(bean.roast_date):null]].map(([l,v])=>`<div><dt>${l}</dt><dd>${known(v)}</dd></div>`).join('')}</dl>${bean.flavor_notes?.length?`<div class="note-block"><h4>Roaster tasting notes</h4><div class="chips">${bean.flavor_notes.map(n=>`<span class="chip">${esc(n)}</span>`).join('')}</div></div>`:''}<div class="note-block"><h4>Your tasting notes</h4><p>${bean.notes?esc(bean.notes).replaceAll('\n','<br>'):'No tasting notes yet. Brew a cup and record what you notice.'}</p></div>${source?`<p class="source-facts">Original source: <a href="${attr(source)}" target="_blank" rel="noopener noreferrer">${esc(new URL(source).hostname)} ${icon('link')}</a></p>`:'<p class="source-facts">Original product URL unknown.</p>'}<div class="detail-divider"></div><div class="section-heading"><h2>Recipes for this coffee</h2><button class="text-link" data-action="new-recipe" data-bean="${attr(id)}">${icon('plus')}New recipe</button></div>${recipes.length?`<div class="recipe-list">${recipes.map(recipeCard).join('')}</div>`:emptyState('Find its best brew','Create an 18 g recipe for this coffee.','','','recipe',true)}<div class="form-actions"><button class="button button-outline" data-action="edit-bean" data-id="${attr(id)}">${icon('edit')}Edit coffee & tasting notes</button></div>`,{wide:true,prefix:'BEAN LIBRARY'});}

// Recipe editor and immutable version history
const defaultPours=()=>[{volume_ml:60,temperature_c:95,flow_ml_s:3.5,pattern:'spiral',pause_s:35,agitation_before:false,agitation_after:false},{volume_ml:76,temperature_c:94,flow_ml_s:3.5,pattern:'circle',pause_s:15,agitation_before:false,agitation_after:false},{volume_ml:76,temperature_c:93,flow_ml_s:3.5,pattern:'spiral',pause_s:15,agitation_before:false,agitation_after:false},{volume_ml:76,temperature_c:92,flow_ml_s:3.5,pattern:'center',pause_s:0,agitation_before:false,agitation_after:false}];
function pourEditor(p,index){return `<div class="step-editor" data-pour="${index}"><div class="step-editor-header"><strong>${index===0?'01 · Bloom':`${String(index+1).padStart(2,'0')} · Pour`}</strong><button type="button" class="icon-button" data-action="remove-pour" aria-label="Remove pour ${index+1}">${icon('trash')}</button></div><div class="field-grid four">${field(`volume_ml_${index}`,'Water (ml)',p.volume_ml,'number','required min="1" max="500" step="1" data-pour-field="volume_ml"')}${field(`temperature_c_${index}`,'Temperature (°C)',p.temperature_c,'number','required min="20" max="100" step="1" data-pour-field="temperature_c"')}${field(`flow_ml_s_${index}`,'Flow (ml/s)',p.flow_ml_s,'number','required min="0.1" max="10" step="0.1" data-pour-field="flow_ml_s"')}${field(`pause_s_${index}`,index===0?'Bloom pause (s)':'Pause after (s)',p.pause_s,'number','required min="0" max="300" step="1" data-pour-field="pause_s"')}${selectField(`pattern_${index}`,'Pour pattern',p.pattern||'circle',['center','circle','spiral'],'data-pour-field="pattern"')}<div class="field"><span class="field-label">Agitation</span><label class="check-field" style="margin-top:0"><input type="checkbox" data-pour-field="agitation_before" ${p.agitation_before?'checked':''}>Before pour</label><label class="check-field" style="margin-top:0"><input type="checkbox" data-pour-field="agitation_after" ${p.agitation_after?'checked':''}>After pour</label></div></div></div>`;}
function readPours(form){return $$('.step-editor',form).map(el=>{const p={};$$('[data-pour-field]',el).forEach(input=>{p[input.dataset.pourField]=input.type==='checkbox'?input.checked:input.tagName==='SELECT'?input.value:Number(input.value);});return p;});}
function recipeFromForm(form){const fd=new FormData(form);return {name:String(fd.get('name')||'').trim(),bean_id:fd.get('bean_id')||null,dose_g:Number(fd.get('dose_g')),ratio:Number(fd.get('ratio')),total_water_ml:Number(fd.get('total_water_ml')),grind_setting:Number(fd.get('grind_setting')),grinder_rpm:Number(fd.get('grinder_rpm')),grinder_enabled:fd.get('grinder_enabled')==='on',cup_type:fd.get('cup_type'),xid:String(fd.get('xid')||'').trim()||null,pours:readPours(form),notes:String(fd.get('notes')||'').trim(),dripper:String(fd.get('dripper')||'').trim()||null,filter:String(fd.get('filter')||'').trim()||null,water_profile:String(fd.get('water_profile')||'').trim()||null};}
function updateRecipeTotals(form){const pours=readPours(form),total=pours.reduce((s,p)=>s+num(p.volume_ml),0),target=num($('[name=total_water_ml]',form).value),dose=num($('[name=dose_g]',form).value);const el=$('#pour-total',form);if(el)el.innerHTML=`<span>Pours total <strong>${fmt(total)} ml</strong></span><span>Recipe target <strong>${fmt(target)} ml</strong></span><span class="${Math.abs(total-target)>.01?'total-warning':''}">${Math.abs(total-target)>.01?`${fmt(Math.abs(total-target))} ml ${total>target?'over':'under'} target`:`${icon('check')} Volumes match`}</span>`;}
function editRecipe(id,beanId){const old=state.recipes.find(r=>String(r.id)===String(id));const recipe=old||{name:'',bean_id:beanId||'',dose_g:18,ratio:16,total_water_ml:288,grind_setting:50,grinder_rpm:80,grinder_enabled:true,cup_type:'omni',pours:defaultPours(),notes:''};openModal(id?'Refine your recipe':'Create a brew recipe',id?'Saving creates a new version. Your previous recipe stays in the history.':'An 18 g starting point. Adjust the recipe for your coffee and taste.',`<form id="recipe-form"><section class="form-section"><h3>Name your brew</h3><div class="field-grid">${field('name','Recipe name',recipe.name,'text','required maxlength="160" placeholder="e.g. A bright morning cup"')}${selectField('bean_id','Coffee',recipe.bean_id||'',[['','No coffee selected'],...state.beans.map(b=>[b.id,`${b.name}${b.roaster?` · ${b.roaster}`:''}`])])}</div></section><section class="form-section"><h3>The foundation</h3><p>Your intended recipe. Card compatibility is checked before a write.</p><div class="field-grid four">${field('dose_g','Coffee dose (g)',recipe.dose_g,'number','required min="1" max="100" step="0.1"')}${field('ratio','Brew ratio (1:…)',recipe.ratio,'number','required min="1" max="100" step="0.001"')}${field('total_water_ml','Total water (ml)',recipe.total_water_ml,'number','required min="1" max="2000" step="1"')}${selectField('cup_type','Brewer type',recipe.cup_type||'omni',[['omni','Omni dripper'],['other','Other dripper'],['xpod','xPod']])}${field('grind_setting','Grind setting',recipe.grind_setting,'number','required min="1" max="200" step="1"')}${field('grinder_rpm','Grinder RPM',recipe.grinder_rpm,'number','required min="1" max="300" step="1"')}<div class="field"><span class="field-label">Grinder</span><label class="check-field" style="margin-top:8px"><input type="checkbox" name="grinder_enabled" ${recipe.grinder_enabled!==false?'checked':''}>Grind before brewing</label></div>${field('xid','Card text ID (optional)',recipe.xid,'text','maxlength="7" pattern="[ -~]{0,7}"','Up to seven plain-text characters.')}</div></section><section class="form-section"><h3>Your brewing setup</h3><p>Optional details for consistent recipes and tasting comparisons.</p><div class="field-grid three">${field('dripper','Dripper / brewer',recipe.dripper,'text','placeholder="e.g. Omni dripper 2"')}${field('filter','Filter',recipe.filter,'text','placeholder="e.g. xBloom paper"')}${field('water_profile','Water profile',recipe.water_profile,'text','placeholder="e.g. Filtered tap water"')}</div></section><section class="form-section"><div class="section-heading"><div><h3>Build your pours</h3><p>Pause is the wait after each pour. Set the first pause for your bloom.</p></div><button type="button" class="button button-small button-outline" data-action="add-pour">${icon('plus')}Add pour</button></div><div id="pour-editors">${(recipe.pours||defaultPours()).map(pourEditor).join('')}</div><div class="summary-strip" id="pour-total"></div></section><section class="form-section">${textarea('notes','Recipe & tasting notes',recipe.notes,'placeholder="Brewing intent, dripper/filter details, and what changed after tasting…"','Use these notes to explain why this version is different.')}</section><div id="recipe-preview"></div><div class="form-error" role="alert"></div><div class="form-actions">${id?`<button type="button" class="button button-danger left" data-action="delete-recipe" data-id="${attr(id)}">${icon('trash')}Delete</button>`:''}<button type="button" class="button button-outline" data-action="preview-recipe">Check NFC compatibility</button><button class="button button-primary" type="submit">${icon('check')}${id?'Save new version':'Save recipe'}</button></div></form>`,{wide:true});state.modalContext={type:'recipe',id};const form=$('#recipe-form');updateRecipeTotals(form);form.addEventListener('input',e=>{if(['dose_g','ratio'].includes(e.target.name)){const dose=num($('[name=dose_g]',form).value),ratio=num($('[name=ratio]',form).value);$('[name=total_water_ml]',form).value=Math.round(dose*ratio);}else if(e.target.name==='total_water_ml'){const dose=num($('[name=dose_g]',form).value);if(dose)$('[name=ratio]',form).value=(num(e.target.value)/dose).toFixed(3);}updateRecipeTotals(form);$('#recipe-preview').innerHTML='';});form.addEventListener('submit',e=>{e.preventDefault();withForm(form,async()=>{const data=recipeFromForm(form);if(!data.pours.length)throw new Error('Add at least one pour.');const total=data.pours.reduce((s,p)=>s+p.volume_ml,0);if(Math.abs(total-data.total_water_ml)>.01)throw new Error('Pour volumes must add up to the recipe’s total water.');await api(id?`/api/recipes/${encodeURIComponent(id)}`:'/api/recipes',{method:id?'PATCH':'POST',body:data});closeModal();await refresh();toast(id?'A new recipe version is saved.':'Recipe saved to your library.');});});}
function pourTimeline(recipe){let water=0;return `<div class="pour-timeline">${(recipe.pours||[]).map((p,i)=>{water+=num(p.volume_ml);return `<div class="pour-row"><div class="pour-number">${i+1}</div><div class="pour-copy"><h4>${i===0?'Bloom':`Pour ${i+1}`} · ${fmt(p.temperature_c)} °C</h4><p>${esc(human(p.pattern))} pattern · ${fmt(p.flow_ml_s)} ml/s${num(p.pause_s)?` · ${fmt(p.pause_s)} s pause`:''}${p.agitation_before?' · Agitate before':''}${p.agitation_after?' · Agitate after':''}</p></div><div class="pour-amount">${fmt(p.volume_ml)} ml<small>${fmt(water)} ml total</small></div></div>`;}).join('')}</div>`;}
function recipeMetrics(recipe){return `<div class="recipe-preview-grid">${[[`${fmt(recipe.dose_g)} g`,'COFFEE DOSE'],[`1:${fmt(recipe.ratio)}`,'BREW RATIO'],[`${fmt(recipe.total_water_ml)} ml`,'TOTAL WATER'],[`${fmt(recipe.grind_setting)}`,'GRIND SETTING']].map(([v,l])=>`<div class="metric-tile"><strong>${v}</strong><span>${l}</span></div>`).join('')}</div>`;}
async function viewRecipe(id,version=null){const current=state.recipes.find(r=>String(r.id)===String(id));if(!current)return;showModalLoading('Your brew recipe');try{const versions=list(await api(`/api/recipes/${encodeURIComponent(id)}/versions`));const historical=version?versions.find(v=>Number(v.version)===Number(version)):null;const r=historical?.recipe||historical?.data||historical||current;const recipe={...current,...r};const old=version&&Number(version)!==Number(current.version);openModal(recipe.name,beanName(recipe.bean_id),`<div class="badge-row"><span class="pill ${old?'orange':''}">Version ${num(recipe.version,1)}${old?' · Previous version':''}</span><span class="pill gray">${recipe.cup_type==='xpod'?'xPod':recipe.cup_type==='other'?'Other dripper':'Omni dripper'}</span><span class="pill gray">${fmt(recipe.grinder_rpm)} RPM${recipe.grinder_enabled===false?' · Grinder off':''}</span></div>${recipeMetrics(recipe)}${recipe.dripper||recipe.filter||recipe.water_profile?`<dl class="info-grid"><div><dt>Dripper</dt><dd>${known(recipe.dripper,'Not recorded')}</dd></div><div><dt>Filter</dt><dd>${known(recipe.filter,'Not recorded')}</dd></div><div><dt>Water</dt><dd>${known(recipe.water_profile,'Not recorded')}</dd></div></dl>`:''}<div class="section-heading"><h2>Pour schedule</h2><span class="muted" style="font-size:10px">${recipe.pours?.length||0} steps</span></div>${pourTimeline(recipe)}${recipe.notes?`<div class="note-block"><h4>Recipe & tasting notes</h4><p>${esc(recipe.notes).replaceAll('\n','<br>')}</p></div>`:''}<details><summary>Version history · ${versions.length||1} saved ${versions.length===1?'version':'versions'}</summary><div class="details-content version-list">${versions.length?versions.map(v=>`<div class="version-item"><div><strong>Version ${num(v.version,1)}${Number(v.version)===Number(current.version)?' · Current':''}</strong><p>${date(v.created_at||v.updated_at,true)}</p></div><button class="button button-small button-outline" data-action="recipe-version" data-id="${attr(id)}" data-version="${attr(v.version)}">View</button></div>`).join(''):'<p class="muted">The first version is saved with this recipe.</p>'}</div></details><div class="form-actions"><button class="button button-outline" data-action="edit-recipe" data-id="${attr(id)}">${icon('edit')}Edit current recipe</button><button class="button button-primary" data-action="choose-card" data-id="${attr(id)}">${icon('card')}Prepare a card</button></div>`,{wide:true,prefix:'YOUR BREW RECIPE'});}catch(e){closeModal();toast(e.message,true);}}
function encodingField(value){const labels={dose_g:'Coffee dose',ratio:'Brew ratio',total_water_ml:'Total water',grind_setting:'Grind setting',grinder_rpm:'Grinder RPM',volume_ml:'Pour volume',temperature_c:'Temperature',flow_ml_s:'Flow rate',pause_s:'Pause'};const match=String(value||'').match(/^pours\[(\d+)\]\.(.+)$/);return match?`Pour ${Number(match[1])+1} · ${labels[match[2]]||human(match[2])}`:labels[value]||human(value||'Recipe value');}
function previewHtml(preview){
  const errors=preview.errors||[],diffs=preview.differences||[],warnings=preview.warnings||[],effective=preview.effective||preview.encoded_recipe||{};
  return `${errors.length?callout(errors.map(esc).join('<br>'),'danger','This recipe cannot be encoded yet.'):callout(preview.compatible===false?'This recipe needs adjustments before it can be written.':'The recipe can be represented on a compatible card. Review any changes below.','info','NFC compatibility')}
  ${warnings.length?callout(warnings.map(esc).join('<br>'),'warning'):''}
  ${diffs.length?`<div class="table-wrap"><table><thead><tr><th>Field</th><th>Intended</th><th>On card</th></tr></thead><tbody>${diffs.map(d=>typeof d==='string'?`<tr><td colspan="3">${esc(d)}</td></tr>`:`<tr><td>${esc(encodingField(d.field||d.path||d.message))}</td><td>${known(d.intended??d.original??d.requested,'—')}</td><td>${known(d.effective??d.encoded??d.actual,'—')}</td></tr>`).join('')}</tbody></table></div>`:!errors.length?'<p class="muted" style="font-size:11px">No encoding differences were reported.</p>':''}
  ${effective?.dose_g?`<details><summary>View the NFC-compatible recipe</summary><div class="details-content">${recipeMetrics(effective)}${pourTimeline(effective)}</div></details>`:''}`;
}

// Reviewed profile import
function sampleProfile(){return {schema_version:1,bean:{name:'Example coffee · replace before importing',roaster:null,product_url:null,country:null,region:null,farm:null,elevation:null,process:null,variety:null,roast_level:null,roast_date:null,flavor_notes:[],notes:'',provenance:{source:'synthetic-example',reviewed:'false'}},recipe:{name:'Example 18 g recipe',dose_g:18,ratio:16,total_water_ml:288,grind_setting:50,grinder_rpm:80,grinder_enabled:true,cup_type:'omni',pours:defaultPours(),notes:'AI starting recommendation. Adjust to your coffee, dripper, filter, and taste.'}};}
function importProfile(profile=null){const initial=profile||state.importProfile;openModal('Bring in a coffee profile','Review the coffee facts and recipe recommendation before saving.',`<div class="progress-steps"><span class="current"><b>1</b>Add profile</span><i class="progress-line"></i><span><b>2</b>Review</span><i class="progress-line"></i><span><b>3</b>Save to library</span></div><form id="import-form"><div class="file-drop">${icon('upload')}<label for="profile-file">Choose a JSON profile, or paste one below.</label><input id="profile-file" type="file" accept="application/json,.json"></div><div class="field"><label for="profile-json">Structured coffee profile</label><textarea id="profile-json" class="code-area" required spellcheck="false" placeholder='{"schema_version": 1, "bean": {...}, "recipe": {...}}'>${initial?esc(JSON.stringify(initial,null,2)):''}</textarea><small>Source facts belong under bean. Brewing recommendations belong under recipe.</small></div><div class="inline-actions mt-16"><button type="button" class="text-link" data-action="load-example">Load a clearly labeled example ${icon('arrow')}</button></div><div class="form-error" role="alert"></div><div class="form-actions"><button type="button" class="button button-outline" data-action="close-modal">Cancel</button><button class="button button-primary" type="submit">Review profile ${icon('arrow')}</button></div></form>`,{wide:true});$('#profile-file').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;if(file.size>2*1024*1024){toast('Choose a JSON file smaller than 2 MB.',true);return;}$('#profile-json').value=await file.text();});$('#import-form').addEventListener('submit',e=>{e.preventDefault();withForm(e.target,async()=>{let profile;try{profile=JSON.parse($('#profile-json').value);}catch{throw new Error('The profile is not valid JSON. Check its braces, quotes, and commas.');}const preview=await api('/api/import/preview',{method:'POST',body:{profile}});state.importProfile=profile;showImportReview(profile,preview);});});}
function reviewSourceDetails(bean){
  const fields=[['name','Coffee name'],['roaster','Roaster'],['country','Country'],['region','Region'],['farm','Farm / producer'],['elevation','Elevation'],['process','Process'],['variety','Variety'],['roast_level','Roast level'],['roast_date','Roast date']];
  const source=safeUrl(bean.product_url),photo=safeUrl(bean.photo_url);
  const provenance=Object.entries(bean.provenance||{});
  const rendered=new Set([...fields.map(([key])=>key),'product_url','photo_url','flavor_notes','notes','rating','provenance']);
  const additional=Object.entries(bean).filter(([key])=>!rendered.has(key));
  return `<details class="source-review"><summary>All coffee & source details</summary><div class="details-content">
    <dl class="info-grid">${fields.map(([key,label])=>`<div><dt>${label}</dt><dd>${known(bean[key])}</dd></div>`).join('')}<div><dt>Your rating</dt><dd>${bean.rating?`${esc(bean.rating)} / 5`:'Not rated'}</dd></div></dl>
    <div class="note-block"><h4>Original product URL</h4><p class="break">${source?`<a href="${attr(source)}" target="_blank" rel="noopener noreferrer">${esc(bean.product_url)}</a>`:'Unknown'}</p></div>
    <div class="note-block"><h4>Roaster tasting notes</h4><p>${bean.flavor_notes?.length?bean.flavor_notes.map(esc).join(', '):'Unknown'}</p></div>
    <div class="note-block"><h4>Your tasting notes</h4><p>${bean.notes?esc(bean.notes).replaceAll('\n','<br>'):'None supplied'}</p></div>
    ${photo?`<div class="note-block"><h4>Coffee bag photo</h4><p class="break"><a href="${attr(photo)}" target="_blank" rel="noopener noreferrer">${esc(bean.photo_url)}</a></p></div>`:''}
    <h4>Where these details came from</h4>${provenance.length?`<dl class="source-provenance">${provenance.map(([key,value])=>`<div><dt>${esc(human(key))}</dt><dd>${esc(typeof value==='string'?value:JSON.stringify(value)).replaceAll('\n','<br>')}</dd></div>`).join('')}</dl>`:'<p class="muted" style="font-size:11px">No field-level source notes were supplied.</p>'}
    ${additional.length?`<h4>Additional supplied details</h4><dl class="source-provenance">${additional.map(([key,value])=>`<div><dt>${esc(human(key))}</dt><dd>${known(typeof value==='object'&&value!==null?JSON.stringify(value):value)}</dd></div>`).join('')}</dl>`:''}
  </div></details>`;
}
function showImportReview(profile,preview){
  const bean=preview.bean||profile.bean||{},recipe=preview.recipe||profile.recipe||{},warnings=preview.warnings||[];
  openModal('Review before you save','These details will create a coffee profile and its first recipe version.',
    `<div class="progress-steps"><span><b>✓</b>Add profile</span><i class="progress-line"></i><span class="current"><b>2</b>Review</span><i class="progress-line"></i><span><b>3</b>Save to library</span></div>
    ${warnings.length?callout(warnings.map(esc).join('<br>'),'warning'):''}
    <div class="review-grid"><div class="review-box"><div class="eyebrow">COFFEE FACTS</div><h4>${known(bean.name)}</h4><p>Roaster: ${known(bean.roaster)}<br>Origin: ${known(bean.country)}<br>Process: ${known(bean.process)}<br>Variety: ${known(bean.variety)}<br>Roast: ${known(bean.roast_level)}</p></div><div class="review-box"><div class="eyebrow">BREWING RECOMMENDATION</div><h4>${known(recipe.name)}</h4><p>${fmt(recipe.dose_g)} g coffee · 1:${fmt(recipe.ratio)} ratio<br>${fmt(recipe.total_water_ml)} ml water · ${recipe.pours?.length||0} pours<br>Grind ${fmt(recipe.grind_setting)} · ${fmt(recipe.grinder_rpm)} RPM<br>${recipe.cup_type==='omni'?'Omni dripper':esc(human(recipe.cup_type))}</p></div></div>
    ${reviewSourceDetails(bean)}
    ${recipe.notes?`<div class="note-block mt-16"><h4>Recipe rationale</h4><p>${esc(recipe.notes).replaceAll('\n','<br>')}</p></div>`:''}
    <details><summary>Additional recipe settings</summary><dl class="info-grid"><div><dt>Dripper</dt><dd>${known(recipe.dripper)}</dd></div><div><dt>Filter</dt><dd>${known(recipe.filter)}</dd></div><div><dt>Water profile</dt><dd>${known(recipe.water_profile)}</dd></div><div><dt>Grinder</dt><dd>${recipe.grinder_enabled===false?'Disabled':'Enabled'}</dd></div><div><dt>Card text ID</dt><dd>${known(recipe.xid,'Not supplied')}</dd></div><div><dt>Recommendation</dt><dd>${recipe.recommendation===false?'User-provided recipe':'Brewing recommendation'}</dd></div></dl></details>
    ${pourTimeline(recipe)}
    <form id="approve-import-form"><label class="check-field"><input name="approved" type="checkbox" required>I have reviewed the available source facts and the suggested recipe. I approve saving this profile.</label><div class="form-error" role="alert"></div><div class="form-actions"><button type="button" class="button button-outline" data-action="back-import">Back to edit</button><button class="button button-primary" type="submit">${icon('check')}Approve & save profile</button></div></form>`,{wide:true});
  $('#approve-import-form').addEventListener('submit',e=>{e.preventDefault();withForm(e.target,async()=>{await api('/api/import/approve',{method:'POST',body:{profile,approved:true}});state.importProfile=null;closeModal();await refresh();toast('Coffee profile and recipe saved.');});});
}

// Physical card inventory, backups, and explicitly approved jobs
function editCard(id){const card=state.cards.find(c=>String(c.id)===String(id))||{};openModal(id?'Edit card details':'Register a custom card','Give the physical card a label you can recognize on your desk.',`<form id="card-form"><div class="field-grid"><div class="span-full">${field('label','Physical card label',card.label,'text','required maxlength="100" placeholder="e.g. Green card · 01"','Put this label on the card so duplicate UIDs cannot cause confusion.')}</div><div class="span-full">${field('uid','UID (optional until first read)',card.uid,'text','pattern="[0-9A-Fa-f :\\-]{16,24}" placeholder="E0…"','Use the UID displayed by Proxmark. Multiple cards may share a UID.')}</div><div class="span-full">${textarea('notes','Card notes',card.notes,'placeholder="Color, identifying marks, or details about this tag…"')}</div></div><div class="form-error" role="alert"></div><div class="form-actions">${id?`<button type="button" class="button button-danger left" data-action="delete-card" data-id="${attr(id)}">${icon('trash')}Delete record</button>`:''}<button type="button" class="button button-outline" data-action="close-modal">Cancel</button><button class="button button-primary" type="submit">${icon('check')}${id?'Save details':'Register card'}</button></div></form>`);$('#card-form').addEventListener('submit',e=>{e.preventDefault();withForm(e.target,async()=>{const fd=new FormData(e.target),data={label:String(fd.get('label')).trim(),uid:String(fd.get('uid')||'').replace(/[ :\-]/g,'').toUpperCase()||null,type:'custom',notes:String(fd.get('notes')||'').trim()};await api(id?`/api/cards/${encodeURIComponent(id)}`:'/api/cards',{method:id?'PATCH':'POST',body:data});closeModal();await refresh();toast(id?'Card details updated.':'Card registered. Save its first backup next.');});});}
async function viewCard(id){const card=state.cards.find(c=>String(c.id)===String(id));if(!card)return;showModalLoading(card.label);try{const backups=list(await api(`/api/cards/${encodeURIComponent(id)}/backups`));state.modalContext={type:'card',id,backups};openModal(card.label,'Match this label to the physical card before any read or write.',`<div class="badge-row"><span class="pill gray">Custom NFC card</span>${card.verified_at?'<span class="pill">Read-back verified</span>':'<span class="pill orange">Not verified on device</span>'}</div><dl class="info-grid"><div><dt>UID</dt><dd class="mono">${known(card.uid,'Not read yet')}</dd></div><div><dt>Inventory ID</dt><dd class="mono">${esc(card.id)}</dd></div><div><dt>Current recipe</dt><dd>${card.recipe_id?esc(recipeName(card.recipe_id)):'Not assigned'}</dd></div></dl>${card.notes?`<div class="note-block"><p>${esc(card.notes)}</p></div>`:''}${card.needs_fresh_read?callout('The previous operation was interrupted or failed. Read this card again before another write.','danger','Fresh read required.'):''}${!backups.length?callout('Read this physical card with the Windows bridge before writing. You can also import a reference dump to preview recipes.','warning','First, preserve the original.'):''}<div class="section-heading"><div><h2>Card backups</h2><p>Saved contents are retained for read-back checks and recovery.</p></div><button class="text-link" data-action="import-card-backup" data-id="${attr(id)}">${icon('upload')}Import dump</button></div>${backups.length?`<div class="table-wrap"><table><thead><tr><th>Saved backup</th><th>Contents</th><th>Actions</th></tr></thead><tbody>${backups.map((backup,i)=>`<tr><td><strong>${String(backup.source||'').startsWith('failed-readback-')?'Failed readback evidence':backup.original?'Original backup':`Backup ${backups.length-i}`}</strong><small>${date(backup.created_at,true)}</small></td><td><code>${esc((backup.sha256||backup.hash||backup.id).slice(0,12))}…</code><small>${backup.block_count?`${backup.block_count} blocks · `:''}${backup.source==='import'?'Imported reference':backup.source==='simulation'?'Simulation':backup.source==='hardware'?'Hardware read':String(backup.source||'').startsWith('failed-readback-')?'Failed readback evidence':'Unrecognized backup source'}</small></td><td><div class="inline-actions"><a class="icon-button" aria-label="Download backup" href="/api/cards/${encodeURIComponent(id)}/backups/${encodeURIComponent(backup.id)}/download" download>${icon('download')}</a><button class="button button-small button-outline" data-action="restore-card" data-id="${attr(id)}" data-backup="${attr(backup.id)}" ${!['hardware','simulation'].includes(backup.source)?'disabled title="Only successful hardware or simulation backups can be restored"':''}>Restore</button></div></td></tr>`).join('')}</tbody></table></div>`:emptyState('No backup saved yet','Read the card with your Windows bridge, or import the JSON dump from a read of this card.','','','folder',true)}<div class="form-actions"><button class="button button-quiet left" data-action="edit-card" data-id="${attr(id)}">${icon('edit')}Edit details</button><button class="button button-outline" data-action="read-card" data-id="${attr(id)}">${icon('download')}Read & back up</button><button class="button button-primary" data-action="choose-recipe" data-id="${attr(id)}" ${!backups.length?'disabled':''}>${icon('recipe')}Prepare recipe</button></div>`,{wide:true,prefix:'CARD INVENTORY'});state.modalContext={type:'card',id,backups};}catch(e){closeModal();toast(e.message,true);}}
function importCardBackup(id){const card=state.cards.find(c=>String(c.id)===String(id));openModal('Save a card backup',`Import a reference Proxmark JSON dump for ${card?.label||'this card'}.`,`${callout('Imported dumps support recipe previews. A fresh read through your Windows bridge is still required before a physical write or restore.','warning')}<form id="backup-form"><div class="file-drop">${icon('upload')}<label for="backup-file">Choose a Proxmark JSON dump.</label><input id="backup-file" type="file" accept="application/json,.json"></div><div class="field"><label for="backup-json">Dump contents</label><textarea id="backup-json" class="code-area" spellcheck="false" required placeholder='{"Created":"proxmark3","FileType":"15693 v4",…}'></textarea></div><label class="check-field"><input type="checkbox" required>I have checked that this dump corresponds to the card labeled “${esc(card?.label)}”.</label><div class="form-error" role="alert"></div><div class="form-actions"><button type="button" class="button button-outline" data-action="view-card" data-id="${attr(id)}">Back</button><button class="button button-primary" type="submit">${icon('shield')}Save backup</button></div></form>`,{wide:true});$('#backup-file').addEventListener('change',async e=>{const file=e.target.files?.[0];if(file){if(file.size>2*1024*1024){toast('Choose a JSON file smaller than 2 MB.',true);return;}$('#backup-json').value=await file.text();}});$('#backup-form').addEventListener('submit',e=>{e.preventDefault();withForm(e.target,async()=>{let dump;try{dump=JSON.parse($('#backup-json').value);}catch{throw new Error('This is not valid JSON. Choose the .json version of your Proxmark dump.');}await api(`/api/cards/${encodeURIComponent(id)}/backups`,{method:'POST',body:{dump}});await refresh({renderPage:false});await viewCard(id);toast('Card backup saved.');});});}
function chooseCard(recipeId){if(!state.cards.length){toast('Register a card and save a backup first.');location.hash='cards';closeModal();return;}openModal('Choose a card','Pick the labeled physical card you want to prepare.',`<div class="recipe-list">${state.cards.map(c=>`<div class="version-item"><div><strong>${esc(c.label)}</strong><p>${esc(cardBackupState(c).label)}</p></div><button class="button button-small button-outline" data-action="prepare-card" data-id="${attr(c.id)}" data-recipe="${attr(recipeId)}" ${!num(c.backup_count)?'disabled':''}>Review ${icon('arrow')}</button></div>`).join('')}</div>`,{narrow:true});}
function chooseRecipe(cardId){if(!state.recipes.length){toast('Create a recipe in your library first.');closeModal();location.hash='recipes';return;}openModal('Choose a recipe',`Prepare a recipe for ${cardLabel(cardId)}.`, `<div class="recipe-list">${state.recipes.map(r=>`<div class="version-item"><div><strong>${esc(r.name)}</strong><p>${fmt(r.dose_g)} g · ${fmt(r.total_water_ml)} ml · Version ${r.version||1}</p></div><button class="button button-small button-outline" data-action="prepare-card" data-id="${attr(cardId)}" data-recipe="${attr(r.id)}">Review ${icon('arrow')}</button></div>`).join('')}</div>`);}
async function prepareCard(cardId,recipeId){showModalLoading('Review your card recipe');try{const preview=await api(`/api/cards/${encodeURIComponent(cardId)}/preview`,{method:'POST',body:{recipe_id:recipeId}});const card=state.cards.find(c=>String(c.id)===String(cardId));const recipe=state.recipes.find(r=>String(r.id)===String(recipeId));openModal('Review the card write',`${recipe?.name||'Recipe'} → ${card?.label||'Card'}`,`${recipe?recipeMetrics(recipe):''}${previewHtml(preview)}${callout('Only this reviewed recipe version should be written. Card-specific identity and header data must be preserved.','info')}<div class="form-actions"><button class="button button-outline" data-action="view-card" data-id="${attr(cardId)}">Back to card</button><button class="button button-primary" data-action="confirm-write" data-id="${attr(cardId)}" data-recipe="${attr(recipeId)}" ${preview.compatible===false||preview.errors?.length?'disabled':''}>Continue to confirmation ${icon('arrow')}</button></div>`,{wide:true});state.modalContext={type:'preview',cardId,recipeId,preview,version:preview.recipe_version||recipe?.version};}catch(e){closeModal();toast(e.message,true);}}
function confirmJob(kind,cardId,{recipeId=null,backupId=null}={}){
  const card=state.cards.find(c=>String(c.id)===String(cardId));if(!card)return;
  const isRead=kind==='read',bridge=state.status.bridge||{},previous=state.modalContext;
  const simulated=isSimulation(bridge);
  const recipe=state.recipes.find(r=>String(r.id)===String(recipeId));
  const reviewedVersion=previous?.version||recipe?.version;
  const differences=kind==='write'?(previous?.preview?.differences||[]):[];
  openModal(simulated?`Simulate a card ${kind}`:isRead?'Read and back up this card':kind==='restore'?'Confirm a card restore':'Confirm this card write',simulated?'This job uses simulated card memory. No physical card or Proxmark will be accessed.':isRead?'A read saves the card’s current contents without changing it.':'Approval applies to this one job and this labeled physical card.',
    `${!bridge.online?callout('Start the Windows bridge before creating this job. A fresh connection is required for approval.','warning'):isSimulation(bridge)?callout('The bridge is in simulation mode. This job will not modify a physical card.','warning'):''}
    <div class="note-block"><h4>${esc(card.label)}</h4><p>UID: <span class="mono">${known(card.uid,'Not read yet')}</span>${recipeId?`<br>Recipe: ${esc(recipeName(recipeId))}${reviewedVersion?` · Version ${reviewedVersion}`:''}`:''}${backupId?`<br>Restore backup: <span class="mono">${esc(backupId)}</span>`:''}</p></div>
    ${differences.length?previewHtml(previous.preview):''}
    <form id="job-form">
      ${!isRead?field('confirm_label',simulated?'Type the simulated card label to confirm':'Type the physical card label to confirm','','text',`required autocomplete="off" placeholder="${attr(card.label)}"`):''}
      <label class="check-field"><input type="checkbox" name="confirm" required>${simulated?`I approve a simulated ${kind} for “${esc(card.label)}”. No physical card or Proxmark will be accessed.`:isRead?`The card labeled “${esc(card.label)}” is the only card on the Proxmark.`:`I have placed the card labeled “${esc(card.label)}” on the Proxmark. I approve this ${kind==='restore'?'restore':'write'} and its read-back verification.`}</label>
      ${differences.length?'<label class="check-field"><input type="checkbox" name="accept_encoding_changes" required>I accept the listed differences between my intended recipe and the recipe encoded on this card.</label>':''}
      <div class="form-error" role="alert"></div><div class="form-actions"><button type="button" class="button button-outline" data-action="view-card" data-id="${attr(cardId)}">Cancel</button><button class="button ${kind==='restore'?'button-danger':'button-primary'}" type="submit" ${!bridge.online?'disabled':''}>${icon(isRead?'download':kind==='restore'?'refresh':'card')}${simulated?`Queue simulated ${kind}`:isRead?'Queue card read':kind==='restore'?'Approve restore':'Approve this write'}</button></div>
    </form>`,{wide:differences.length>0});
  $('#job-form').addEventListener('submit',e=>{e.preventDefault();withForm(e.target,async()=>{
    const fd=new FormData(e.target);
    if(!isRead&&fd.get('confirm_label')!==card.label)throw new Error(simulated?'The label must match this simulated card exactly.':'The label must match exactly. Check the physical card before approving.');
    const body={kind,card_id:cardId,confirm:true,bridge_mode:bridge.mode};
    if(!isRead)body.confirm_label=fd.get('confirm_label');
    if(recipeId){body.recipe_id=recipeId;body.version=reviewedVersion;body.accept_encoding_changes=fd.get('accept_encoding_changes')==='on';}
    if(backupId)body.backup_id=backupId;
    const job=await api('/api/jobs',{method:'POST',body});closeModal();await refresh();
    toast(`${human(kind)} request queued.${job.mode==='simulation'?' Simulation only.':' Follow its progress in NFC cards.'}`);location.hash='cards';
  });});
}
function resolveJob(id){
  const job=state.jobs.find(j=>String(j.id)===String(id));if(!job)return;
  openModal('Resolve an interrupted card job','Stop the Windows bridge before clearing this interrupted operation.',
    `${callout('The application cannot determine whether this card was fully written. Resolving marks the operation as failed and requires a fresh read before another write. It does not retry the operation.','warning')}
    <div class="note-block"><h4>${esc(job.label||cardLabel(job.card_id))}</h4><p>${esc(human(job.kind))} · started ${date(job.started_at||job.created_at,true)}</p></div>
    <form id="resolve-form">${field('confirm_label','Physical card label','','text','required autocomplete="off"')}
    <label class="check-field"><input type="checkbox" name="confirm_bridge_stopped" required>I have fully stopped the Windows bridge process and confirmed it is no longer performing a card operation.</label>
    <div class="form-error" role="alert"></div><div class="form-actions"><button type="button" class="button button-outline" data-action="close-modal">Cancel</button><button class="button button-danger" type="submit">${icon('warning')}Mark interrupted & require new read</button></div></form>`);
  $('#resolve-form').addEventListener('submit',e=>{e.preventDefault();withForm(e.target,async()=>{
    const fd=new FormData(e.target);await api(`/api/jobs/${encodeURIComponent(id)}/resolve`,{method:'POST',body:{confirm_bridge_stopped:fd.get('confirm_bridge_stopped')==='on',confirm_label:String(fd.get('confirm_label')||'')}});closeModal();await refresh();toast('Interrupted job resolved. Read the card again before writing.');
  });});
}

// Settings and utility dialogs
function bridgeHelp(){openModal('Connect your Windows bridge','The bridge links your local server to the USB Proxmark on your PC.',`${callout('Start in simulation mode. Enable hardware writes only after validating the client path, card reads, and local backups.','info')}<ol class="data-list"><li>Create a bridge token in Settings. It is shown only once.</li><li>On your Windows PC, open the project’s bridge setup instructions and configure the server’s LAN URL, bridge token, Proxmark client path, and USB port.</li><li>Start the bridge and confirm that its status appears online here.</li><li>Register a physical card, read its contents, and review the saved backup.</li><li>Review a recipe’s NFC representation. Each write or restore requires a separate confirmation.</li></ol><div class="note-block"><h4>Your known setup</h4><p>Iceman/RRG client · PM3 GENERIC · USB port COM6 in your supplied log. Verify the port before connecting.</p></div><p class="muted" style="font-size:11px">The bridge makes outbound requests to this application. Keep the Proxmark interface private on Windows.</p><div class="form-actions"><button class="button button-primary" data-action="close-modal">Got it</button></div>`);}
async function createToken(kind){openModal(kind==='bridge'?'Create a Windows bridge token':'Create an import API token','This grants access to the local application. Store it securely.',`<form id="token-form">${callout(kind==='bridge'?'Use a bridge token only in the Windows Proxmark bridge configuration.':'Use this token when transferring a reviewed coffee profile from Codex.','info')}${state.settings.tokens_configured?.includes(kind)?callout('Creating a new token revokes the existing token of this type. Update the client configuration after copying it.','warning'):''}<label class="check-field"><input type="checkbox" required>I will keep this token out of GitHub and shared files.</label><div class="form-error" role="alert"></div><div class="form-actions"><button type="button" class="button button-outline" data-action="close-modal">Cancel</button><button class="button button-primary" type="submit">${icon('lock')}Create token</button></div></form>`,{narrow:true});$('#token-form').addEventListener('submit',e=>{e.preventDefault();withForm(e.target,async()=>{const result=await api('/api/tokens',{method:'POST',body:{kind}});openModal('Copy your token now','It will not be shown again after this dialog closes.',`${callout('Save this token in your local configuration or password manager. Never commit it to your repository.','warning')}<div class="field"><label for="generated-token">${kind==='bridge'?'Bridge':'Import API'} token</label><textarea id="generated-token" class="mono" readonly rows="3" spellcheck="false">${esc(result.token)}</textarea></div><div class="form-actions"><button class="button button-outline" data-action="copy-token">${icon('copy')}Copy token</button><button class="button button-primary" data-action="close-modal">I’ve saved it</button></div>`);});});}
function importFormat(){openModal('The coffee profile format','A portable JSON profile for your Codex-to-library workflow.',`${callout('This is a synthetic example. Replace it with verified product details and your reviewed recipe before importing.','warning')}<div class="field"><label for="format-json">Example profile</label><textarea id="format-json" class="code-area" readonly spellcheck="false">${esc(JSON.stringify(sampleProfile(),null,2))}</textarea></div><div class="note-block mt-16"><h4>Authenticated import API</h4><p>Use <code>Authorization: Bearer YOUR_API_TOKEN</code>. Validate the profile with <code>POST /api/import/preview</code>, then save an approved profile with <code>POST /api/import/approve</code>. Both requests include a <code>profile</code> object; approval also requires <code>approved: true</code>.</p></div><div class="form-actions"><button class="button button-outline" data-action="copy-format">${icon('copy')}Copy example</button><button class="button button-primary" data-action="import">Import a profile</button></div>`,{wide:true});}
function confirmDelete(resource,id){const object=state[resource].find(r=>String(r.id)===String(id));if(!object)return;openModal(`Delete ${resource==='beans'?'coffee':resource==='recipes'?'recipe':'card record'}?`,`“${object.name||object.label}” will be removed from your workspace.`,`${callout(resource==='cards'?'This deletes the inventory record only. It does not change the physical card. Records with saved history may be protected from deletion.':'Related records may prevent deletion. The application will explain if this item is still in use.','warning')}<form id="delete-form"><div class="form-error" role="alert"></div><div class="form-actions"><button type="button" class="button button-outline" data-action="close-modal">Keep it</button><button class="button button-danger" type="submit">${icon('trash')}Delete record</button></div></form>`,{narrow:true});$('#delete-form').addEventListener('submit',e=>{e.preventDefault();withForm(e.target,async()=>{await api(`/api/${resource}/${encodeURIComponent(id)}`,{method:'DELETE'});closeModal();await refresh();toast('Record deleted.');});});}
async function copyText(text){if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text);}else{const input=document.createElement('textarea');input.value=text;input.style.position='fixed';input.style.opacity='0';(modal.open?$('#modal-content'):document.body).append(input);input.select();const ok=document.execCommand('copy');input.remove();if(!ok)throw new Error('Select the text and copy it manually.');}toast('Copied to clipboard.');}
async function action(name,el){const id=el?.dataset.id;switch(name){
  case 'close-modal':closeModal();break;
  case 'new-bean':editBean();break;case 'edit-bean':editBean(id);break;case 'view-bean':viewBean(id);break;
  case 'new-recipe':editRecipe(null,el?.dataset.bean);break;case 'edit-recipe':editRecipe(id);break;case 'view-recipe':await viewRecipe(id);break;case 'recipe-version':await viewRecipe(id,el.dataset.version);break;
  case 'delete-bean':confirmDelete('beans',id);break;case 'delete-recipe':confirmDelete('recipes',id);break;case 'delete-card':confirmDelete('cards',id);break;
  case 'new-card':editCard();break;case 'edit-card':editCard(id);break;case 'view-card':await viewCard(id);break;
  case 'import':importProfile();break;case 'back-import':importProfile(state.importProfile);break;
  case 'load-example':$('#profile-json').value=JSON.stringify(sampleProfile(),null,2);toast('Synthetic example loaded. Replace its details before saving.');break;
  case 'import-card-backup':importCardBackup(id);break;case 'read-card':confirmJob('read',id);break;case 'restore-card':confirmJob('restore',id,{backupId:el.dataset.backup});break;
  case 'choose-card':chooseCard(id);break;case 'choose-recipe':chooseRecipe(id);break;case 'prepare-card':await prepareCard(id,el.dataset.recipe);break;case 'confirm-write':confirmJob('write',id,{recipeId:el.dataset.recipe});break;
  case 'add-pour':{const container=$('#pour-editors');const pours=readPours($('#recipe-form'));pours.push({volume_ml:50,temperature_c:92,flow_ml_s:3.5,pattern:'circle',pause_s:0,agitation_before:false,agitation_after:false});container.innerHTML=pours.map(pourEditor).join('');updateRecipeTotals($('#recipe-form'));$('#recipe-preview').innerHTML='';break;}
  case 'remove-pour':{const form=$('#recipe-form'),pour=el.closest('.step-editor'),index=Number(pour.dataset.pour),pours=readPours(form);if(pours.length===1){toast('Keep at least one pour.',true);break;}pours.splice(index,1);$('#pour-editors').innerHTML=pours.map(pourEditor).join('');updateRecipeTotals(form);$('#recipe-preview').innerHTML='';break;}
  case 'preview-recipe':{const form=$('#recipe-form');if(!form.reportValidity())break;el.disabled=true;try{const preview=await api('/api/recipes/preview',{method:'POST',body:recipeFromForm(form)});$('#recipe-preview').innerHTML=previewHtml(preview);$('#recipe-preview').scrollIntoView({behavior:'smooth',block:'nearest'});}finally{el.disabled=false;}break;}
  case 'refresh':await refresh();toast('Workspace refreshed.');break;
  case 'cancel-job':await api(`/api/jobs/${encodeURIComponent(id)}/cancel`,{method:'POST'});await refresh();toast('Queued card job cancelled.');break;
  case 'resolve-job':resolveJob(id);break;
  case 'bridge-help':bridgeHelp();break;case 'create-api-token':await createToken('api');break;case 'create-bridge-token':await createToken('bridge');break;
  case 'copy-token':await copyText($('#generated-token').value);break;case 'import-format':importFormat();break;case 'copy-format':await copyText($('#format-json').value);break;
  case 'logout':await api('/api/session',{method:'DELETE'});state.session=await api('/api/session');showAuth();break;
}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el&&!el.disabled){e.preventDefault();action(el.dataset.action,el).catch(err=>toast(err.message,true));}});
document.addEventListener('input',e=>{if(e.target.id==='page-search'){const pos=e.target.selectionStart;state.query=e.target.value;render();const search=$('#page-search');search.focus();try{search.setSelectionRange(pos,pos);}catch{}}});
$('#menu-toggle').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('open');$('#nav-backdrop').hidden=!open;$('#menu-toggle').setAttribute('aria-expanded',String(open));});
$('#nav-backdrop').addEventListener('click',()=>{$('#sidebar').classList.remove('open');$('#nav-backdrop').hidden=true;$('#menu-toggle').setAttribute('aria-expanded','false');});
$('#session-button').addEventListener('click',()=>location.hash='settings');
modal.addEventListener('cancel',e=>{if(!state.session.authenticated)e.preventDefault();else document.body.classList.remove('login-only');});
modal.addEventListener('click',e=>{if(e.target===modal&&state.session.authenticated){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
window.addEventListener('hashchange',changeRoute);
async function init(){hydrateIcons();changeRoute();renderNavigation();try{state.session=await api('/api/session');if(state.session.authenticated)await refresh();else showAuth();}catch(e){$('#main').innerHTML=`<div class="error-state"><h2>The workspace is taking a moment.</h2><p>${esc(e.message)}</p><button class="button button-outline" data-action="refresh">${icon('refresh')}Try again</button></div>`;}setInterval(()=>{if(state.session.authenticated&&!document.hidden)refresh({renderPage:!modal.open&&!state.query&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName),quiet:true});},30000);}
init();
